 // The closed G08 cutover did not authorize legacy recovery or stage promotion.
 // P2's accepted outer port still owns its situated, non-numerical evaluation.
 // R4: call the accepted native rest/sleep rules, but transfer the resulting
 // HP/Qi into the private A08 owner before its normal affliction tick/sync.
 // G08's existing trusted-input normal event will CAS-seal the joint Player/World
 // delta, including ecology, within the same click/submit boundary.
 function nativeRest(g,name){
  if(!nativeInput()||g.combate||g.pregunta||g.terminado)return 'El reposo sólo puede iniciarse mediante una acción válida fuera de combate.';
  const c=context(g),original=g.avanzarAflicciones;
  if(c.pending||c.pendingDeaths.length||c.deathOutbox.length)return 'Termina primero las operaciones pendientes.';
  if(c.dots.length||g.normalizarAflicciones().length)return 'El reposo con aflicciones activas requiere su tratamiento específico antes de continuar.';
  let synced=false;
  g.avanzarAflicciones=function(...args){
   if(synced)fail('ORDINARY_REST_SECOND_AFFLICTION_TICK');
   const f=frame(c),hp=g.player.hp,qi=g.player.qi;
   if(!Number.isSafeInteger(hp)||hp<c.hp||hp>f.stats.HP_MAX.value||!Number.isSafeInteger(qi)||qi<c.qi||qi>f.stats.QI_MAX.value)fail('ORDINARY_REST_PRIVATE_NUMERIC_FRAME');
   c.hp=hp;c.qi=qi;synced=true;
   return original.apply(g,args);
  };
  try{
   const answer=old[name].call(g);
   if(synced){receipt(c,name==='cmd_dormir'?'ORDINARY_NATIVE_SLEEP':'ORDINARY_NATIVE_REST',{room:g.pos,ecology:c.ecology,source:'ACCEPTED_CAMPAIGN_NATIVE_REST'});sync(g,c);g.actualizarBarra();}
   return answer;
  }finally{delete g.avanzarAflicciones;}
 }
